tests:
def check_basic():
    assert tuple(two_sum([2,7,11,15], 9)) == (0,1)

def check_middle():
    assert tuple(two_sum([3,2,4], 6)) == (1,2)

def check_negatives():
    assert tuple(two_sum([-1,-2,-3,-4], -7)) == (2,3)

def check_simple():
    assert is_balanced('()') is True

def check_nested():
    assert is_balanced('{[()]}') is True

def check_bad_order():
    assert is_balanced('([)]') is False

def check_unclosed():
    assert is_balanced('(((') is False

def check_ignores_text():
    assert is_balanced('a(b)c') is True

def check_compress():
    assert run_length_encode('aaaabbbb') == 'a4b4'

def check_no_gain():
    assert run_length_encode('abc') == 'abc'

def check_tie_returns_original():
    assert run_length_encode('aaabbc') == 'aaabbc'

def check_empty():
    assert run_length_encode('') == ''

def check_single_run():
    assert run_length_encode('aaaa') == 'a4'
